"""Source-reviewed range, callable, product, and sum-type contracts."""


def section(title, *paragraphs, table=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if table is not None:
        result["table"] = table
    return result


def table(columns, rows):
    return {"columns": columns, "rows": rows}


def datatype(name, header, summary, *sections, covers=None):
    result = {"name": name, "header": header, "summary": summary,
              "sections": list(sections)}
    if covers:
        result["covers"] = covers
    return result


